package com.onlinelibrary.controller;
import com.onlinelibrary.model.User; import com.onlinelibrary.util.PasswordUtil; import com.onlinelibrary.util.Validation; import com.onlinelibrary.dao.impl.UserDAOImpl; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.IOException;
@WebServlet({"/librarian/members","/librarian/member-form"}) public class MemberManagementServlet extends HttpServlet {
 protected void doGet(HttpServletRequest r,HttpServletResponse s)throws IOException,ServletException{try{UserDAOImpl d=new UserDAOImpl();r.setAttribute("members",d.findMembers(r.getParameter("q")));String id=r.getParameter("id");if(id!=null)r.setAttribute("member",d.findById(Long.parseLong(id)).orElseThrow());WebSupport.view(r,s,r.getServletPath().endsWith("member-form")?"member-form.jsp":"members.jsp");}catch(Exception e){WebSupport.fail(r,s,e);}}
 protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException,ServletException{try{UserDAOImpl d=new UserDAOImpl();if("deactivate".equals(r.getParameter("action")))d.deactivate(Long.parseLong(r.getParameter("id")));else{String id=r.getParameter("id"),membership=r.getParameter("membershipId"),name=r.getParameter("name"),email=r.getParameter("email");Validation.member(name,email,membership);User u=new User();u.setMembershipId(membership);u.setName(name);u.setEmail(email);u.setStatus("ACTIVE");if(id==null||id.isBlank()){String password=r.getParameter("password");if(password==null||password.length()<8)throw new IllegalArgumentException("Initial password must contain at least 8 characters");u.setPasswordHash(PasswordUtil.hash(password));d.createMember(u);}else{u.setId(Long.parseLong(id));d.updateMember(u);}}s.sendRedirect(r.getContextPath()+"/librarian/members?message=Member+saved");}catch(Exception e){WebSupport.fail(r,s,e);}}
}
